from abc import ABCMeta


class NavigatablePage(object):
    __metaclass__ = ABCMeta

    def __init__(self, tool):
        self._tool = tool

    @staticmethod
    def navigate_to(navigator=None):
        """
        navigate to page by navigator

        :return: object, corresponding page instance
        """
        navigator.navigate()
